      "composition": "\u9999\u9644 \u7092 2\u9322\n\u7d2b\u8607 2\u9322\n\u7518\u8349 \u7099 7\u5206\n\u9673\u76ae \u53bb\u767d 1\u9322\n\u52a0\u8591\u3001\u8525\u714e\u3002",
      "effects": "\u7406\u6c23\u89e3\u8868\u3002",
      "indications": "\u5916\u611f\u98a8\u5bd2\uff0c\u5167\u6709\u6c23\u6eef\u3002\u75c7\u898b\u60e1\u5bd2\u8eab\u71b1\uff0c\u982d\u75db\u7121\u6c57\uff0c\u80f8\u8118\u75de\u60b6\uff0c\u4e0d\u601d\u98f2\u98df\uff0c\u820c\u82d4\u8584\u767d\uff0c\u8108\u6d6e\u3002\n\u5a66\u4eba\u598a\u5a20\uff0c\u5916\u611f\u98a8\u5bd2\uff0c\u6c23\u9b31\u8af8\u75c7\u3002",
      "rationale": "\u672c\u65b9\u9069\u7528\u65bc\u7d20\u6709\u6c23\u6eef\u9ad4\u8cea\uff0c\u5fa9\u611f\u5916\u90aa\u8005\u3002\u65b9\u4e2d\u9999\u9644\uff0c\u958b\u9b31\u6563\u6eef\uff0c\u8abf\u6c23\u758f\u809d\uff0c\u5584\u758f\u6c23\u9b31\uff1b\u7d2b\u8607\u8449\u5916\u958b\u76ae\u6bdb\uff0c\u758f\u6563\u98a8\u5bd2\uff0c\u5167\u89e3\u9b31\u7d50\uff0c\u5584\u89e3\u8840\u9b31\uff1b\u9673\u76ae\u517c\u884c\u8868\u88e1\uff0c\u5065\u80c3\u53bb\u75f0\uff0c\u4e26\u80fd\u6563\u9b31\uff1b\u751f\u8591\u8f9b\u6eab\u52a9\u7d2b\u8607\u8449\u758f\u98a8\u89e3\u8868\uff0c\u7099\u7518\u8349\u548c\u4e2d\uff0c\u8abf\u548c\u8af8\u85e5\uff0c\u6276\u52a9\u5143\u6c23\u3002",
      "diagnosticCriteria": "\u767c\u71b1\u60e1\u5bd2\u3002\n\u80f8\u8118\u75de\u60b6\u4e0d\u66a2\u3002\n\u82d4\u767d\u8584\u3002\n\u8108\u6d6e\u3002",
      "modifications": "\u7d0d\u5446\uff1a\u52a0\u5c71\u67e5\u3001\u9ea5\u82bd\u3001\u795e\u9eb4\u3002\n\u54b3\u55fd\uff1a\u52a0\u534a\u590f\u3001\u674f\u4ec1\u3001\u6851\u767d\u76ae\u3001\u6b3e\u51ac\u82b1\u3002\n\u98a8\u5bd2\u982d\u75db\uff1a\u52a0\u5ddd\u828e\u3001\u7d30\u8f9b\u3001\u767d\u82b7\u3002\n\u517c\u7009\u75e2\uff1a\u52a0\u832f\u82d3\u3001\u767d\u672e\u3002\n\u5614\u5410\uff1a\u52a0\u85ff\u9999\u3001\u534a\u590f\u3002\n\u8179\u75db\uff1a\u52a0\u6728\u9999\u3001\u767d\u828d\u3002\n\u9f3b\u6d41\u6e05\u6d95\u9f3b\u585e\uff1a\u52a0\u8525\u767d\u3001\u834a\u82a5\u3002\n\u633e\u71b1\uff1a\u52a0\u9ec3\u82a9\u3001\u9023\u7ff9\u3002\n\u80c3\u8118\u8139\u6eff\uff1a\u52a0\u67b3\u6bbc\u3001\u539a\u6734\u3002\n\u598a\u5a20\u6c23\u6eef\u5916\u611f\uff1a\u52a0\u767d\u672e\u3001\u9ec3\u82a9\u3002",
