      "composition": "\u83df\u7d72\u5b50\n\u4e94\u5473\u5b50\n\u67b8\u675e\u5b50\n\u8986\u76c6\u5b50\n\u8eca\u524d\u5b50",
      "effects": "\u88dc\u814e\u56fa\u7cbe\u3002",
      "indications": "\u7528\u65bc\u814e\u865b\u907a\u7cbe\uff0c\u967d\u75ff\u65e9\u6cc4\uff0c\u5c0f\u4fbf\u5f8c\u9918\u701d\u4e0d\u6e05\uff0c\u4e45\u4e0d\u751f\u80b2\uff0c\u53ca\u6c23\u8840\u5169\u865b\uff0c\u9b1a\u9aee\u65e9\u767d\u7b49\u75c7\u3002",
      "rationale": "\u53e4\u8b02\u672c\u65b9\u6709\u6dfb\u7cbe\u3001\u88dc\u9ad3\u3001\u76ca\u814e\u7684\u4f5c\u7528\uff0c\u7a31\u4e4b\u70ba\u7a2e\u5b50\u65b9\u3002\u65b9\u4e2d\u83df\u7d72\u5b50\u3001\u67b8\u675e\u5b50\u88dc\u814e\u967d\uff0c\u76ca\u7cbe\u8840\uff1b\u4e94\u5473\u5b50\u3001\u8986\u76c6\u5b50\u88dc\u814e\u56fa\u6f80\uff1b\u8eca\u524d\u5b50\u4ea6\u6709\u88dc\u809d\u814e\u4e4b\u529f\u3002\u738b\u80af\u5802\u4e91\uff1a\u300c\u5609\u9756\u4e01\u4ea5\u5f97\u65bc\u5ee3\u4fe1\u912d\u4e2d\u51fd\u5b85\uff0c\u85e5\u6b62\u4e94\u5473\uff0c\u70ba\u7e41\u884d\u5b97\u55e3\u7a2e\u5b50\u7b2c\u4e00\u65b9\u4e5f\uff0c\u6545\u540d\u3002\u300d\uff08\u300a\u5a66\u79d1\u6e96\u7e69\u300b\uff09\u300c\u884d\u300d\u70ba\u5ee3\u5e03\u5e38\u6d41\u4e4b\u610f\uff0c\u672c\u65b9\u4e94\u85e5\u7686\u7528\u300c\u7a2e\u5b50\u300d\uff0c\u53d6\u300c\u4ee5\u5b50\u88dc\u5b50\u300d\u4e4b\u7fa9\uff0c\u6709\u6dfb\u7cbe\u88dc\u814e\uff0c\u52a9\u65bc\u7e41\u884d\u5b97\u55e3\u7684\u4f5c\u7528\uff0c\u6545\u7a31\u300c\u4e94\u5b50\u884d\u5b97\u4e38\u300d\u3002",
