      "effects": "\u990a\u9670\u6e05\u71b1\u3001\u6f64\u80ba\u5316\u75f0\u3002",
      "indications": "\u80ba\u814e\u9670\u8667\uff0c\u865b\u706b\u4e0a\u708e\u8b49\u3002\u54bd\u5589\u4e7e\u71e5\uff0c\u75bc\u75db\uff0c\u54b3\u55fd\uff0c\u6c23\u5598\uff0c\u54b3\u75f0\u5e36\u8840\uff0c\u624b\u8db3\u5fc3\u71b1\uff0c\u820c\u7d05\u5c11\u82d4\uff0c\u8108\u7d30\u6578\u3002",
      "rationale": "\u672c\u65b9\u70ba\u6cbb\u80ba\u814e\u9670\u8667\u3001\u865b\u706b\u4e0a\u708e\u6240\u81f4\u54b3\u55fd\u75f0\u8840\u7684\u5e38\u7528\u65b9\u3002\u65b9\u4e2d\u767e\u5408\u3001\u9ea5\u51ac\u990a\u9670\u6f64\u80ba\u751f\u6d25\u70ba\u541b\uff1b\u751f\u5730\u3001\u719f\u5730\u3001\u7384\u53c3\u6ecb\u9670\u6e05\u71b1\u3001\u5229\u54bd\u5589\u70ba\u81e3\uff1b\u7576\u6b78\u3001\u828d\u85e5\u990a\u8840\u76ca\u9670\uff0c\u6854\u6897\u3001\u8c9d\u6bcd\u6e05\u80ba\u5316\u75f0\u6b62\u54b3\u70ba\u4f50\uff1b\u7518\u8349\u5354\u8abf\u8af8\u85e5\u70ba\u4f7f\u4e5f\u3002",
      "diagnosticCriteria": "1.\u54bd\u4e7e\u53e3\u71e5\u3002\n2.\u54b3\u55fd\u6c23\u5598\u3002\n3.\u75f0\u4e2d\u5e36\u8840\u3002\n4.\u820c\u7d05\u5c11\u82d4\u3002\n5.\u8108\u7d30\u6578\u3002",
      "modifications": "1.\u80f8\u8105\u8139\u6eff\uff1a\u52a0\u67b3\u5be6\u3001\u67f4\u80e1\u3002\n2.\u5931\u8072\u54bd\u75db\uff1a\u52a0\u5929\u51ac\u3001\u77e5\u6bcd\u3002\n3.\u54b3\u55fd\u6c23\u5598\uff1a\u52a0\u674f\u4ec1\u3001\u539a\u6734\u3001\u67b3\u6bbc\u3002\n4.\u80ba\u7d50\u6838\uff1a\u52a0\u767d\u82a8\u3001\u767e\u90e8\u3001\u590f\u67af\u8349\u3002\n5.\u75f0\u591a\u9ec3\u7a20\uff1a\u52a0\u74dc\u851e\u3001\u7af9\u8339\u3002\n6.\u54b3\u75f0\u5e36\u8840\uff1a\u52a0\u767d\u8305\u6839\u3001\u4ed9\u9db4\u8349\u3002\n7.\u54af\u8840\u80f8\u60b6\uff1a\u5408\u4e03\u5398\u6563\u3002\n8.\u652f\u6c23\u7ba1\u64f4\u5f35\u54af\u8840\uff1a\u52a0\u9752\u9edb\u3002",
      "modernApplications": "\u80ba\u7d50\u6838\u3001\u80ba\u764c\u3001\u652f\u6c23\u7ba1\u64f4\u5f35\u54af\u8840\u3001\u80ba\u708e\u5f8c\u671f\u3001\u6162\u6027\u809d\u708e\u3001\u6162\u6027\u54bd\u708e\u3001\u6162\u6027\u54bd\u75db\u3001\u6241\u5e73\u75a3\u3002",
