      "effects": "\u758f\u98a8\u6e05\u71b1\u3001\u5ba3\u80ba\u6b62\u54b3\u3002",
      "indications": "\u5916\u611f\u98a8\u71b1\u8b49\u3002\u54b3\u55fd\u3001\u54bd\u5fae\u75db\u3001\u53e3\u5fae\u6e34\u3001\u8eab\u71b1\u4e0d\u751a\u3001\u820c\u5c16\u7d05\u3001\u82d4\u767d\u8584\u3001\u8108\u6d6e\u6578\u3002",
      "rationale": "\u672c\u65b9\u70ba\u8f9b\u6dbc\u8f15\u5291\uff0c\u662f\u98a8\u6eab\u521d\u8d77\uff0c\u90aa\u5728\u80ba\u885b\uff0c\u8868\u71b1\u5c1a\u8f15\u7684\u5e38\u7528\u65b9\u3002\u65b9\u4e2d\u6851\u8449\u3001\u83ca\u82b1\u7518\u82e6\u6027\u6dbc\uff0c\u80fd\u758f\u6563\u4e0a\u7126\u98a8\u71b1\uff0c\u53c8\u80fd\u6e05\u900f\u80ba\u7d93\u4e4b\u71b1\u5408\u70ba\u541b\u85e5\uff0c\u4e26\u4ee5\u4e4b\u70ba\u65b9\u540d\u3002\u81e3\u4ee5\u8f9b\u6dbc\u4e4b\u8584\u8377\uff0c\u4ee5\u52a0\u5f37\u6851\u3001\u83ca\u758f\u6563\u98a8\u71b1\u4e4b\u529b\uff1b\u6854\u6897\u8207\u674f\u4ec1\u76f8\u914d\uff0c\u4e00\u5347\u4e00\u964d\uff0c\u80fd\u5ba3\u964d\u80ba\u6c23\uff0c\u6b62\u54b3\u5316\u75f0\uff1b\u9023\u7ff9\u6e05\u71b1\u89e3\u6bd2\uff0c\u53c8\u6e05\u4e2d\u6709\u900f\uff0c\u53ef\u589e\u5f37\u758f\u98a8\u6e05\u71b1\u4e4b\u6548\uff1b\u8606\u6839\u6e05\u71b1\u751f\u6d25\u6b62\u6e34\uff0c\u4ff1\u70ba\u4f50\u85e5\uff1b\u7518\u8349\u8abf\u548c\u8af8\u85e5\uff0c\u8207\u6854\u6897\u76f8\u914d\uff0c\u5584\u80fd\u6e05\u5229\u54bd\u5589\uff0c\u5316\u75f0\u6b62\u54b3\u70ba\u4f7f\u3002",
      "diagnosticCriteria": "\u51e1\u5916\u611f\u98a8\u71b1\u521d\u8d77\u54b3\u55fd\u3001\u54bd\u5fae\u75db\u3001\u53e3\u5fae\u6e34\u3001\u8eab\u71b1\u4e0d\u751a\u8005\u7686\u53ef\u4f7f\u7528\u3002",
      "modifications": "\u54bd\u75db\u751a\u8005\uff1a\u52a0\u725b\u84a1\u5b50\u3001\u9280\u82b1\u3001\u5c04\u5e72\u3002\n\u54b3\u55fd\u751a\u8005\uff1a\u52a0\u6b3e\u51ac\u82b1\u3001\u681d\u851e\u3002\n\u75f0\u4e2d\u633e\u8840\uff1a\u52a0\u767d\u8305\u6839\u3001\u6241\u67cf\u3002\n\u71b1\u751a\u53e3\u6e34\uff1a\u52a0\u77f3\u818f\u3001\u77e5\u6bcd\u3001\u5929\u82b1\u7c89\u3002\n\u6d41\u884c\u6027\u7d50\u819c\u708e\uff1a\u52a0\u767d\u84ba\u85dc\u3001\u6c7a\u660e\u5b50\u3001\u590f\u67af\u8349\u3002\n\u80ba\u71b1\u751a\u8005\uff1a\u52a0\u9ec3\u82a9\u3002",
      "modernApplications": "\u672c\u65b9\u6d88\u708e\u9000\u71b1\uff0c\u6b62\u54b3\u55fd\u3002\u7528\u65bc\u611f\u5192\u3001\u6d41\u611f\u3001\u6025\u6027\u652f\u6c23\u7ba1\u708e\u3001\u4e0a\u547c\u5438\u9053\u611f\u67d3\u3001\u54b3\u55fd\u3001\u76ee\u7729\u3001\u6d41\u884c\u6027\u7d50\u819c\u708e\u3002",
